type ExactFixtureResponse = { status: number; body: Buffer; headers: Record<string, string>; delayMs: number };
type ExactFixtureHandler = () => ExactFixtureResponse | Promise<ExactFixtureResponse>;
type ExactFixtureEntry = { transport: "same-origin-http-fixture"; respond: ExactFixtureHandler } | { transport: "browser-network" };
let exactFixtureServer: Server | null = null;
let exactFixturePage: Page | null = null;
let exactFixtureTestState: ExactTestState | null = null;
const exactFixtureHandlers = new Map<ExactReadbackPath, ExactFixtureEntry>();
const exactFixtureServerFindings: string[] = [];
const exactFixtureDeliveries: ExactFixtureDelivery[] = [];
let nextExactFixtureDeliveryId = 0;

function exactResponse({
  status = 200,
  body = Buffer.alloc(0),
  headers = {},
  delayMs = 0
}: {
  status?: number;
  body?: Buffer;
  headers?: Record<string, string>;
  delayMs?: number;
} = {}): ExactFixtureResponse {
  return { status, body, headers, delayMs };
}

function exactJsonResponse(value: unknown, {
  status = 200,
  headers = {},
  delayMs = 0
}: {
  status?: number;
  headers?: Record<string, string>;
  delayMs?: number;
} = {}): ExactFixtureResponse {
  return exactResponse({
    status,
    body: Buffer.from(JSON.stringify(value), "utf8"),
    headers: { "Content-Type": "application/json; charset=utf-8", ...headers },
    delayMs
  });
}

function exactRawJsonResponse(body: string, options: { status?: number; delayMs?: number } = {}): ExactFixtureResponse {
  return exactResponse({
    status: options.status,
    body: Buffer.from(body, "utf8"),
    headers: { "Content-Type": "application/json; charset=utf-8" },
    delayMs: options.delayMs
  });
}

function setExactFixtureHandler(page: Page, pathname: ExactReadbackPath, respond: ExactFixtureHandler) {
  if (page !== exactFixturePage) throw new Error("Exact fixture page identity diverged");
  exactFixtureHandlers.set(pathname, { transport: "same-origin-http-fixture", respond });
}

function useBrowserNetworkForExactFixture(page: Page, pathname: ExactReadbackPath) {
  if (page !== exactFixturePage) throw new Error("Exact fixture page identity diverged");
  exactFixtureHandlers.set(pathname, { transport: "browser-network" });
}

async function installLiveTruthRoutes(page: Page, options: { attestationStatus?: number; attestationSourceCommit?: string; observedTime?: number } = {}) {
  const fixtures = liveTruthFixtures({ attestationSourceCommit: options.attestationSourceCommit, observedTime: options.observedTime });
  exactFixtureHandlers.clear();
  setExactFixtureHandler(page, "/api/tree", () => exactJsonResponse(fixtures.readback, {
    headers: { "Cache-Control": "no-store" },
    delayMs: 25
  }));
  setExactFixtureHandler(page, "/api/provenance", () => exactJsonResponse(fixtures.provenance, { headers: { "Cache-Control": "no-store" } }));
  setExactFixtureHandler(page, "/__clover/deployment-attestation.json", () => options.attestationStatus === 204
    ? exactResponse({ status: 204 })
    : exactJsonResponse(fixtures.attestation));
}

async function resetLiveTruthRoutes(page: Page, options: { attestationStatus?: number; attestationSourceCommit?: string; observedTime?: number } = {}) {
  await installLiveTruthRoutes(page, options);
}

async function gotoExactApp(page: Page) {
  const trace = readbackRequestTraces.get(page);
  if (trace) {
    if (trace.requests.some(({ terminal }) => terminal === "pending")) {
      throw new Error("Exact app navigation cannot cross a pending Node request-trace entry");
    }
    exactDocumentBoundaries.set(page, {
      requestId: trace.nextSequence + 1,
      generationId: trace.nextGeneration + 1
    });
  }
  return page.goto(`${expectedBrowserOrigin}/`, { waitUntil: "networkidle" });
}

