  const conditionResults = exactConditionResults({
    raw,
    serverByteCount: completionBody.serverByteCount,
    serverSha256: completionBody.serverSha256,
    clientByteCount: completionBody.clientByteCount,
    clientSha256: completionBody.clientSha256,
    attestationServerSha256: completionBody.attestationServerSha256,
    attestationClientSha256: completionBody.attestationClientSha256,
    requestObservedAt: reportingRequestObservedAt,
    githubObservedAt: reportingGithubObservedAt
  });
  const completion = { ...completionBody, conditionResults };
  const adjudication = {
    rawEvent: raw,
    endpoint: raw.endpoint,
    method: raw.method,
    generation,
    status: 200 as const,
    serverByteCount: completion.serverByteCount,
    serverSha256: completion.serverSha256,
    clientByteCount: completion.clientByteCount,
    clientSha256: completion.clientSha256,
    clientConsumptionStatus: completion.clientConsumptionStatus,
    parsedPayloadResult: completion.parsedPayloadResult,
    uiReconciliationResult: completion.uiReconciliationResult,
    laterAttestationResult: completion.laterAttestationResult,
    adjudication: "LOCAL_HARNESS_REPORTING_ARTIFACT_CONFIRMED" as const,
    reason: exactLocalReportingArtifactReason
  };
  oneEvent.conditionResults = conditionResults;
  oneEvent.rawEvents = [raw];
  oneEvent.independentCompletionEvidence = [completion];
  oneEvent.adjudications = [adjudication];
  const postArtifactProof = (id: number, firstSequence: number): ExactLocalPostArtifactGenerationProof => {
    const requests = exactReadbackPaths.map((pathname, index): ExactGateRequestProof => {
      const requestSequence = firstSequence + index;
      const deliveryId = 900_000 + requestSequence;
      const bodySha256 = sha256(`synthetic-post-artifact:${id}:${pathname}`);
      const byteCount = 200 + requestSequence;
      return {
        pathname,
        request: {
          sequence: requestSequence, generation: id, clientRequestIdentity: requestSequence,
          clientApplicationGeneration: id, clientTestStateId: testState.id as string, pathname,
          status: 200, terminal: "finished", failure: null, transport: "same-origin-http-fixture",
          fixtureBodyState: "delivered", fixtureDeliveryId: deliveryId, fixtureBodySha256: bodySha256
        },
        client: {
          documentRequestId: requestSequence, documentGeneration: id, requestIdentity: requestSequence,
          applicationGeneration: id, endpoint: pathname, url: `${expectedBrowserOrigin}${pathname}`, method: "GET",
          testStateId: testState.id as string, status: 200, deliveryId, serverByteCount: byteCount,
          serverSha256: bodySha256, consumptionStatus: "complete", clientByteCount: byteCount,
          clientSha256: bodySha256, parsedJson: true, signalAborted: false, error: null
        },
        delivery: {
          id: deliveryId, requestIdentity: requestSequence, applicationGeneration: id, pathname, method: "GET",
          url: `${expectedBrowserOrigin}${pathname}`, testStateId: testState.id as string, status: 200,
          byteCount, bodySha256, finished: true, cancelled: false, error: null, bodyUtf8ByteCount: byteCount
        }
      };
    });
    const body = { id, requests };
    return { ...body, canonicalSha256: sha256(`${canonicalJson(body)}\n`) };
  };
  const artifactProof = postArtifactProof(generation, sequence - 1);
  const artifactProvenance = artifactProof.requests[1]!;
  artifactProvenance.request.terminal = "failed";
  artifactProvenance.request.failure = "net::ERR_ABORTED";
  artifactProvenance.request.fixtureBodySha256 = completion.serverSha256;
  artifactProvenance.client.serverByteCount = completion.serverByteCount;
  artifactProvenance.client.clientByteCount = completion.clientByteCount;
  artifactProvenance.client.serverSha256 = completion.serverSha256;
  artifactProvenance.client.clientSha256 = completion.clientSha256;
  artifactProvenance.delivery.byteCount = completion.serverByteCount;
  artifactProvenance.delivery.bodyUtf8ByteCount = completion.serverByteCount;
  artifactProvenance.delivery.bodySha256 = completion.serverSha256;
  const artifactAttestation = artifactProof.requests[2]!;
