function buildGate04PriorClosure(scans: AxeScanEvidence[], project: string) {
  const fullPrior = gate04PriorInventory();
  const prior = fullPrior.filter((occurrence) => occurrence.project === project);
  const projectExpectations: Record<string, ReturnType<typeof inventoryDigests>> = {
    "desktop-chromium": {
      occurrences: 3664,
      occurrenceSha256: "089afe551f39c82ef29a28500037e653662388c22d3908b723e4b28d75c6c34e",
      selectorHtmlPairs: 924,
      selectorHtmlPairSha256: gate04SelectorHtmlPairSha256,
      selectors: 795,
      selectorSha256: gate04SelectorSha256
    },
    "mobile-chromium": {
      occurrences: 3140,
      occurrenceSha256: "5f3ccf9fe9c02bcdfd0c99135a1ad65049b504dbc3e3c956d3e3a23528ab652e",
      selectorHtmlPairs: 853,
      selectorHtmlPairSha256: "9db95ea95ab737676734d28dc9ebefcb775d31a5c333658ae5f05224ef28a802",
      selectors: 724,
      selectorSha256: "0d5ad6068a7f9c5ee05c348d23636913dd7278c19d439d2b3b24bc7f9756b10c"
    }
  };
  const expectedProject = projectExpectations[project];
  if (!expectedProject || canonicalJson(inventoryDigests(prior)) !== canonicalJson(expectedProject)) throw new Error(`Gate 0.4 ${project} baseline mismatch`);

  const scansByKey = new Map<string, AxeScanEvidence>();
  for (const scan of scans) {
    const key = `${scan.view}|${scan.state}`;
    if (scansByKey.has(key)) throw new Error(`Duplicate scan while binding Gate 0.4 decorations: ${key}`);
    const bindingBody = { sourceBucket: scan.decorativeBindings.sourceBucket, entries: scan.decorativeBindings.entries };
    if (scan.decorativeBindings.sourceBucket !== "live-dom-decorative-binding" || scan.decorativeBindings.entries.length !== 12 || scan.decorativeBindings.canonicalSha256 !== sha256(`${canonicalJson(bindingBody)}\n`)) throw new Error(`Invalid per-scan decorative binding: ${key}`);
    scansByKey.set(key, scan);
  }
  const current = currentColorOccurrences(scans, project);
  const excludedAxeDecorative = current.flatMap((entry) => {
    const decoration = exactDecorativeOccurrence(entry.occurrence, "current");
    return decoration ? [{ ...entry, bindingKind: decoration.kind, bindingPredicate: decoration.predicate }] : [];
  });
  const meaningfulCurrent = current.filter(({ occurrence }) => exactDecorativeOccurrence(occurrence, "current") === null);
  const currentByKey = new Map<string, number[]>();
  meaningfulCurrent.forEach(({ occurrence }, index) => {
    const key = canonicalJson(occurrence);
    currentByKey.set(key, [...(currentByKey.get(key) ?? []), index]);
  });
  const used = new Set<number>();
  const normalizedMatched: Gate04Occurrence[] = [];
  const substitutions: Array<Gate04Occurrence & { currentHtml: string; substitution: "tree-mark-leaf-aria-hidden" }> = [];
  const liveTruthTimestampSubstitutions: Array<Gate04Occurrence & {
    currentHtml: string;
    substitution: "github-observed-at-source-time-advance" | "request-observed-at-time-advance";
  }> = [];
  const sourceClaimSubstitutions: Array<Gate04Occurrence & { currentSelector: string; currentHtml: string; substitution: string }> = [];
  const selectorDisambiguationSubstitutions: Array<Gate04Occurrence & { currentSelector: string; substitution: string }> = [];
  const decorativePriorMatches: Array<{ occurrence: Gate04Occurrence; sourceBucket: "live-dom-decorative-binding"; bindingKind: "tree-mark-leaf" | "navigation-ordinal"; bindingPredicate: "tree-mark-leaf-glyph" | "sidebar-navigation-ordinal"; bindingCanonicalSha256: string }> = [];
  const unmatchedPriorOccurrences: Array<{ occurrence: Gate04Occurrence; currentOccurrence: Gate04Occurrence; candidateCount: number }> = [];
  for (const occurrence of prior) {
    const decoration = exactDecorativeOccurrence(occurrence, "prior");
    if (decoration) {
      const scan = scansByKey.get(`${occurrence.view}|${occurrence.state}`);
      if (!scan) throw new Error(`Gate 0.4 decorative binding scan missing: ${canonicalJson(occurrence)}`);
      const candidates = scan.decorativeBindings.entries.filter((entry) => entry.kind === decoration.kind
        && entry.predicate === decoration.predicate
        && entry.ordinal === decoration.ordinal
        && entry.accessibleName === decoration.accessibleName
        && entry.sourceBucket === "live-dom-decorative-binding"
        && entry.matchCount === 1
        && entry.outerHTML === decoration.currentHtml
        && entry.childElementCount === 0
        && entry.interactiveDescendantCount === 0);
      if (candidates.length !== 1) throw new Error(`Gate 0.4 decorative prior occurrence expected one exact live-DOM binding and found ${candidates.length}: ${canonicalJson(occurrence)}`);
      decorativePriorMatches.push({
        occurrence,
        sourceBucket: "live-dom-decorative-binding",
        bindingKind: decoration.kind,
        bindingPredicate: decoration.predicate,
        bindingCanonicalSha256: scan.decorativeBindings.canonicalSha256
      });
      normalizedMatched.push(occurrence);
      if (decoration.kind === "tree-mark-leaf") substitutions.push({ ...occurrence, currentHtml: decoration.currentHtml, substitution: "tree-mark-leaf-aria-hidden" });
      continue;
    }
    const liveTruthTimestamp = exactLiveTruthTimestampOccurrence(occurrence);
    const sourceClaim = exactSourceClaimOccurrence(occurrence);
    const selectorDisambiguation = exactSelectorDisambiguationOccurrence(occurrence);
    const currentOccurrence = liveTruthTimestamp
      ? { ...occurrence, html: liveTruthTimestamp.currentHtml }
      : sourceClaim ? { ...occurrence, selector: sourceClaim.currentSelector, html: sourceClaim.currentHtml }
        : selectorDisambiguation ? { ...occurrence, selector: selectorDisambiguation.currentSelector } : occurrence;
    const key = canonicalJson(currentOccurrence);
    const candidates = (currentByKey.get(key) ?? []).filter((index) => !used.has(index));
    if (candidates.length !== 1) {
      unmatchedPriorOccurrences.push({ occurrence, currentOccurrence, candidateCount: candidates.length });
      continue;
    }
    used.add(candidates[0]!);
    normalizedMatched.push(occurrence);
    if (liveTruthTimestamp) liveTruthTimestampSubstitutions.push({ ...occurrence, ...liveTruthTimestamp });
    if (sourceClaim) sourceClaimSubstitutions.push({ ...occurrence, ...sourceClaim });
    if (selectorDisambiguation) selectorDisambiguationSubstitutions.push({ ...occurrence, ...selectorDisambiguation });
  }
  if (unmatchedPriorOccurrences.length > 0) throw new Error(`Gate 0.4 occurrence closure mismatch: ${canonicalJson(unmatchedPriorOccurrences)}`);
  const extras = meaningfulCurrent.filter((_, index) => !used.has(index));
  if (extras.some(({ sourceBucket }) => sourceBucket !== "passes")) throw new Error("Gate 0.4 closure left an unmatched current incomplete target");
  const normalizedDigests = inventoryDigests(normalizedMatched);
  if (canonicalJson(normalizedDigests) !== canonicalJson(expectedProject)) throw new Error(`Gate 0.4 ${project} normalized closure mismatch`);
  const sortedSubstitutions = sortedCanonical(substitutions);
  const sortedLiveTruthTimestampSubstitutions = sortedCanonical(liveTruthTimestampSubstitutions);
  const sortedSourceClaimSubstitutions = sortedCanonical(sourceClaimSubstitutions);
  const sortedSelectorDisambiguationSubstitutions = sortedCanonical(selectorDisambiguationSubstitutions);
  const sortedDecorativePriorMatches = sortedCanonical(decorativePriorMatches);
  const sortedExcludedAxeDecorative = sortedCanonical(excludedAxeDecorative);
  const sortedExtras = sortedCanonical(extras);
  return {
    binding: {
      reportRawSha256: gate04ReportRawSha256,
      attachments: [
        { project: "desktop-chromium", sha256: "0ba237f7284564475063811677645f788650aab83a18142f244ee3760cc7b432", scans: 30 },
        { project: "mobile-chromium", sha256: "0d0ffad60dc467b9ba909601bed0032524433b6309c87ebaa4a2cb07ecbe5bab", scans: 30 }
      ],
      fullInventory: {
        ...inventoryDigests(fullPrior),
        gzipSha256: gate04InventoryGzipSha256,
        gzipBase64: gate04InventoryGzipBase64
      }
    },
    projectBaseline: expectedProject,
    matchedOccurrences: normalizedMatched.length,
    normalizedClosure: normalizedDigests,
    substitutions: {
      count: sortedSubstitutions.length,
      canonicalSha256: sha256(`${canonicalJson(sortedSubstitutions)}\n`),
      exactKind: "tree-mark-leaf-aria-hidden"
    },
    liveTruthTimestampSubstitutions: {
      count: sortedLiveTruthTimestampSubstitutions.length,
      canonicalSha256: sha256(`${canonicalJson(sortedLiveTruthTimestampSubstitutions)}\n`),
      exactKinds: ["github-observed-at-source-time-advance", "request-observed-at-time-advance"]
    },
    sourceClaimSubstitutions: {
      count: sortedSourceClaimSubstitutions.length,
      canonicalSha256: sha256(`${canonicalJson(sortedSourceClaimSubstitutions)}\n`),
      exactKinds: ["github-observation-label", "layer-one-attestation-verified", "layer-one-claim-label", "layer-one-readiness-label", "layer-two-external-hold", "layer-two-readiness-label", "live-state-text-node-normalization", "matching-layer-one-clears-contradictions", "matching-layer-one-enables-preview-action"]
    },
    selectorDisambiguationSubstitutions: {
      count: sortedSelectorDisambiguationSubstitutions.length,
      canonicalSha256: sha256(`${canonicalJson(sortedSelectorDisambiguationSubstitutions)}\n`),
      exactKinds: ["clean-state-status-selector-disambiguated", "footer-selector-disambiguated-by-global-live-region", "readiness-label-selector-disambiguated"]
    },
    decorativePriorOccurrences: {
      count: sortedDecorativePriorMatches.length,
      canonicalSha256: sha256(`${canonicalJson(sortedDecorativePriorMatches)}\n`),
      sourceBucket: "live-dom-decorative-binding",
      treeMarkLeaf: sortedDecorativePriorMatches.filter(({ bindingKind }) => bindingKind === "tree-mark-leaf").length,
      navigationOrdinal: sortedDecorativePriorMatches.filter(({ bindingKind }) => bindingKind === "navigation-ordinal").length
    },
    currentColorOccurrences: current.length,
    meaningfulColorOccurrences: meaningfulCurrent.length,
    excludedAxeDecorative: {
      count: sortedExcludedAxeDecorative.length,
      canonicalSha256: sha256(`${canonicalJson(sortedExcludedAxeDecorative)}\n`),
      passes: sortedExcludedAxeDecorative.filter(({ sourceBucket }) => sourceBucket === "passes").length,
      incomplete: sortedExcludedAxeDecorative.filter(({ sourceBucket }) => sourceBucket === "incomplete").length
    },
    additionalPreviouslyPassing: {
      count: sortedExtras.length,
      canonicalSha256: sha256(`${canonicalJson(sortedExtras)}\n`),
      allSourceBucketPasses: true
    },
    missing: [],
    closureStatus: "exact-prior-occurrences-closed"
  };
}

async function expectNoHorizontalOverflow(page: Page, view: string) {
  const widths = await page.evaluate((activeView) => {
    const measure = (element: Element | null) => {
      if (!(element instanceof HTMLElement)) return null;
      const bounds = element.getBoundingClientRect();
      return {
        clientWidth: element.clientWidth,
        scrollWidth: element.scrollWidth,
        left: bounds.left,
        right: bounds.right,
        width: bounds.width
      };
    };
    return {
      view: activeView,
      viewportWidth: window.innerWidth,
      document: measure(document.documentElement),
      body: measure(document.body),
      main: measure(document.querySelector(".command-main")),
      panels: Array.from(document.querySelectorAll(".command-panel, .prototype-card, .owner-input-card, .understanding-card, .recommended-packet")).map((panel, index) => {
        const measured = measure(panel);
        if (!measured) throw new Error(`Expected an HTML panel at index ${index}`);
        return { label: panel.querySelector("h2, h3")?.textContent?.trim() ?? `panel-${index + 1}`, ...measured };
      })
    };
  }, view);
  const diagnostic = JSON.stringify(widths, null, 2);
  for (const [label, measured] of [["document", widths.document], ["body", widths.body], ["main", widths.main]] as const) {
    expect(measured, `${label} missing\n${diagnostic}`).not.toBeNull();
    expect(measured!.scrollWidth, `${label} overflow in ${view}\n${diagnostic}`).toBeLessThanOrEqual(measured!.clientWidth);
    expect(measured!.right, `${label} exceeds viewport in ${view}\n${diagnostic}`).toBeLessThanOrEqual(widths.viewportWidth + 0.5);
  }
  for (const panel of widths.panels) {
    expect(panel.scrollWidth, `panel ${panel.label} overflow in ${view}\n${diagnostic}`).toBeLessThanOrEqual(panel.clientWidth);
    expect(panel.left, `panel ${panel.label} starts outside viewport in ${view}\n${diagnostic}`).toBeGreaterThanOrEqual(-0.5);
    expect(panel.right, `panel ${panel.label} exceeds viewport in ${view}\n${diagnostic}`).toBeLessThanOrEqual(widths.viewportWidth + 0.5);
  }
  return widths;
}

function bucketSummary(scans: AxeScanEvidence[], bucket: "passes" | "violations" | "incomplete" | "inapplicable") {
  const rules = scans.flatMap((scan) => scan[bucket]);
  return { ruleRecords: rules.length, nodes: rules.reduce((total, rule) => total + rule.nodes.length, 0) };
}

function expectExactGateOrderedFenceHistory(
  scans: AxeScanEvidence[],
  rejectedAttempts: ExactRejectedGateAttempt[],
  preAxeStartFenceCollisions: ExactPreAxeStartFenceCollision[]
) {
  const scansByKey = new Map(scans.map((scan) => [`${scan.view}|${scan.state}`, scan]));
  const rejectedByKey = new Map(rejectedAttempts.map((attempt) => [`${attempt.view}|${attempt.state}`, attempt]));
  const preAxeByKey = new Map(preAxeStartFenceCollisions.map((collision) => [`${collision.view}|${collision.state}`, collision]));
  const timeline: Array<{ label: string; fence: ExactGateBrowserFence }> = [];
  for (const stateKey of exactAxeStateKeys) {
    const rejected = rejectedByKey.get(stateKey);
    const preAxe = preAxeByKey.get(stateKey);
    const accepted = scansByKey.get(stateKey);
    if (!accepted) throw new Error(`Exact Gate ordered history is missing accepted state ${stateKey}`);
    if (preAxe) timeline.push({ label: `${stateKey}:pre-axe-after`, fence: preAxe.afterFence });
    if (rejected) {
      timeline.push({ label: `${stateKey}:rejected-before`, fence: rejected.beforeFence });
      timeline.push({ label: `${stateKey}:rejected-after`, fence: rejected.afterFence });
    }
    timeline.push({ label: `${stateKey}:accepted-before`, fence: accepted.gateAttemptProof.beforeFence });
    timeline.push({ label: `${stateKey}:accepted-after`, fence: accepted.gateAttemptProof.afterFence });
  }
  let previous: { label: string; fence: ExactGateBrowserFence } | null = null;
  let stableOrigin: string | null = null;
  let stableTestStateId: string | null = null;
  for (const current of timeline) {
    requireExactGateDocumentBoundary(current.fence.trace, current.fence.client, current.label);
    const closed = requireExactGateLedgerClosure(
      current.fence.trace,
      current.fence.client,
      current.fence.localReportingArtifacts
    );
    if (closed.stableOrigin === null || closed.stableTestStateId === null) {
      throw new Error(`Exact Gate ordered history lacks its origin/test-state binding at ${current.label}`);
    }
    stableOrigin ??= closed.stableOrigin;
    stableTestStateId ??= closed.stableTestStateId;
    if (closed.stableOrigin !== stableOrigin || closed.stableTestStateId !== stableTestStateId) {
      throw new Error(`Exact Gate ordered history changed origin/test-state at ${current.label}`);
    }
    if (previous) {
      const before = previous.fence;
      const after = current.fence;
      const prefixEqual = (afterValue: unknown[], beforeValue: unknown[]) =>
        canonicalJson(afterValue.slice(0, beforeValue.length)) === canonicalJson(beforeValue);
      if (after.trace.nextSequence < before.trace.nextSequence
        || after.trace.nextGeneration < before.trace.nextGeneration
        || after.client.nextRequestId < before.client.nextRequestId
        || after.client.nextGeneration < before.client.nextGeneration
        || after.client.documentStartRequestId !== before.client.documentStartRequestId
        || after.client.documentStartGeneration !== before.client.documentStartGeneration
        || after.generation.id < before.generation.id
        || !prefixEqual(after.trace.requests, before.trace.requests)
        || !prefixEqual(after.trace.generations, before.trace.generations)
        || !prefixEqual(after.trace.deliveries, before.trace.deliveries)
        || !prefixEqual(after.trace.aborted, before.trace.aborted)
        || !prefixEqual(after.client.records, before.client.records)
        || !prefixEqual(after.client.generations, before.client.generations)
        || !prefixEqual(after.localReportingArtifacts, before.localReportingArtifacts)) {
        throw new Error(`Exact Gate ordered ledger history diverged between ${previous.label} and ${current.label}`);
      }
    }
    previous = current;
  }
}

function assertExactGateScanAttemptSidecar(
  value: unknown,
  expected: { head: string; project: string; viewport: { width: number; height: number }; scans: AxeScanEvidence[] }
): asserts value is ExactGateScanAttemptSidecar {
  exactKeys(value, ["canonicalSha256", "exactStateKeys", "maxAttemptsPerState", "maxStartFenceCapturesPerAxeAttempt", "preAxeStartFenceCollisions", "project", "rejectedAttempts", "schemaVersion", "source", "summary", "viewport"], "Gate scan-attempt sidecar");
  const { canonicalSha256, ...body } = value;
  if (canonicalSha256 !== sha256(`${canonicalJson(body)}\n`)) throw new Error("Gate scan-attempt sidecar self-hash mismatch");
  exactKeys(value.source, ["head", "repository"], "Gate scan-attempt source");
  if (value.schemaVersion !== gateScanAttemptSidecarSchema || value.source.repository !== exactRepository
    || value.source.head !== expected.head || value.project !== expected.project || value.maxAttemptsPerState !== 2
    || value.maxStartFenceCapturesPerAxeAttempt !== 2
    || canonicalJson(value.viewport) !== canonicalJson(expected.viewport)
    || canonicalJson(value.exactStateKeys) !== canonicalJson(exactAxeStateKeys)
    || !Array.isArray(value.rejectedAttempts) || !Array.isArray(value.preAxeStartFenceCollisions)) {
    throw new Error("Gate scan-attempt sidecar identity mismatch");
  }
  const keys = new Set<string>();
  const rejectedAttempts = value.rejectedAttempts as unknown as ExactRejectedGateAttempt[];
  const preAxeStartFenceCollisions = value.preAxeStartFenceCollisions as unknown as ExactPreAxeStartFenceCollision[];
  const preAxeStateKeyIndexes: number[] = [];
  for (const [collisionIndex, collision] of preAxeStartFenceCollisions.entries()) {
    exactKeys(collision, ["afterFence", "axeAttempt", "beforeTrace", "canonicalSha256", "classification", "execution", "observed", "observer", "reason", "retryAuthorized", "startFenceCaptureAttempt", "state", "view", "viewport"], `Gate pre-Axe collision ${collision.view}|${collision.state}`);
    exactKeys(collision.observed, ["clientNextGeneration", "clientNextRequestId", "fingerprint", "focused", "nodeNextGeneration", "nodeNextSequence", "visibilityState"], `Gate pre-Axe collision ${collision.view}|${collision.state}.observed`);
    const { canonicalSha256: collisionHash, ...collisionBody } = collision;
    const { canonicalSha256: beforeTraceHash, ...beforeTraceBody } = collision.beforeTrace;
    const { canonicalSha256: afterFenceHash, ...afterFenceBody } = collision.afterFence;
    const { canonicalSha256: afterGenerationHash, ...afterGenerationBody } = collision.afterFence.generation;
    const key = `${collision.view}|${collision.state}`;
    if (collisionHash !== sha256(`${canonicalJson(collisionBody)}\n`)
      || beforeTraceHash !== sha256(`${canonicalJson(beforeTraceBody)}\n`)
      || afterFenceHash !== sha256(`${canonicalJson(afterFenceBody)}\n`)
      || afterGenerationHash !== sha256(`${canonicalJson(afterGenerationBody)}\n`)
      || collision.axeAttempt !== 1 || collision.startFenceCaptureAttempt !== 1
      || collision.execution !== "axe-not-executed"
      || collision.classification !== "exact-normal-periodic-refresh-pre-axe-start-fence-collision"
      || collision.reason !== "one-visible-focused-current-periodic-generation-began-during-start-fence-capture-before-axe"
      || collision.retryAuthorized !== true || collision.observed.visibilityState !== "visible"
      || collision.observed.focused !== true
      || !exactAxeStateKeys.includes(key as typeof exactAxeStateKeys[number])
      || canonicalJson(collision.viewport) !== canonicalJson(expected.viewport)) {
      throw new Error(`Gate pre-Axe collision identity mismatch: ${key}`);
    }
    requireExactGateDocumentBoundary(collision.afterFence.trace, collision.afterFence.client, `Gate pre-Axe collision ${key} after fence`);
    requireExactGateLedgerClosure(collision.afterFence.trace, collision.afterFence.client, collision.afterFence.localReportingArtifacts);
    if (collision.afterFence.trace.nextSequence !== collision.beforeTrace.nextSequence + exactReadbackPaths.length
      || collision.afterFence.trace.nextGeneration !== collision.beforeTrace.nextGeneration + 1
      || collision.afterFence.client.nextRequestId !== collision.beforeTrace.nextSequence + exactReadbackPaths.length
      || collision.afterFence.client.nextGeneration !== collision.beforeTrace.nextGeneration + 1
      || collision.afterFence.trace.currentDocumentStartRequestId !== collision.beforeTrace.currentDocumentStartRequestId
      || collision.afterFence.trace.currentDocumentStartGeneration !== collision.beforeTrace.currentDocumentStartGeneration
      || canonicalJson(collision.afterFence.trace.requests.slice(0, collision.beforeTrace.requests.length)) !== canonicalJson(collision.beforeTrace.requests)
      || canonicalJson(collision.afterFence.trace.generations.slice(0, collision.beforeTrace.generations.length)) !== canonicalJson(collision.beforeTrace.generations)
      || canonicalJson(collision.afterFence.trace.deliveries.slice(0, collision.beforeTrace.deliveries.length)) !== canonicalJson(collision.beforeTrace.deliveries)
      || canonicalJson(collision.afterFence.trace.aborted) !== canonicalJson(collision.beforeTrace.aborted)
      || collision.afterFence.localReportingArtifacts.some(({ rawEvent }) => rawEvent.generation > collision.beforeTrace.nextGeneration)
      || collision.observed.nodeNextSequence < collision.beforeTrace.nextSequence
      || collision.observed.nodeNextSequence > collision.afterFence.trace.nextSequence
      || collision.observed.nodeNextGeneration < collision.beforeTrace.nextGeneration
      || collision.observed.nodeNextGeneration > collision.afterFence.trace.nextGeneration
      || collision.observed.clientNextRequestId < collision.beforeTrace.nextSequence
      || collision.observed.clientNextRequestId > collision.afterFence.client.nextRequestId
      || collision.observed.clientNextGeneration < collision.beforeTrace.nextGeneration
      || collision.observed.clientNextGeneration > collision.afterFence.client.nextGeneration
      || collision.observed.nodeNextSequence === collision.beforeTrace.nextSequence
        && collision.observed.nodeNextGeneration === collision.beforeTrace.nextGeneration
        && collision.observed.clientNextRequestId === collision.beforeTrace.nextSequence
        && collision.observed.clientNextGeneration === collision.beforeTrace.nextGeneration
      || canonicalJson(collision.afterFence.fingerprint) !== canonicalJson(collision.observed.fingerprint)) {
      throw new Error(`Gate pre-Axe collision is not one exact closed periodic generation: ${key}`);
    }
    expectExactGateObserverTransition(collision.observer, collision.observed.fingerprint.source, true);
    const previous = preAxeStartFenceCollisions[collisionIndex - 1];
    if (previous && (collision.afterFence.generation.id <= previous.afterFence.generation.id
      || collision.afterFence.trace.nextSequence <= previous.afterFence.trace.nextSequence)) {
      throw new Error(`Gate pre-Axe collision chronology moved backward or reused a settled boundary: ${key}`);
    }
    if (keys.has(key)) throw new Error(`Gate scan-attempt sidecar has a second collision for ${key}`);
    keys.add(key);
    preAxeStateKeyIndexes.push(exactAxeStateKeys.indexOf(key as typeof exactAxeStateKeys[number]));
  }
  if (preAxeStateKeyIndexes.some((value, index) => index > 0 && value <= preAxeStateKeyIndexes[index - 1]!)) {
    throw new Error("Gate pre-Axe collisions are not one strict exactStateKeys subsequence");
  }
  const stateKeyIndexes: number[] = [];
  for (const [attemptIndex, attempt] of rejectedAttempts.entries()) {
    exactKeys(attempt, ["adjudications", "afterFence", "attempt", "axe", "beforeFence", "canonicalSha256", "classification", "decorativeBindings", "execution", "liveNodeBindings", "observer", "reason", "retryAuthorized", "state", "view", "viewport"], `Gate rejected attempt ${attempt.view}|${attempt.state}`);
    const { canonicalSha256: attemptHash, ...attemptBody } = attempt;
    if (attemptHash !== sha256(`${canonicalJson(attemptBody)}\n`) || attempt.attempt !== 1
      || attempt.execution !== "axe-executed" || attempt.classification !== "exact-normal-periodic-refresh-collision"
      || attempt.reason !== "one-visible-focused-current-to-refreshing-to-next-current-periodic-generation-intersected-axe"
      || attempt.retryAuthorized !== true || !exactAxeStateKeys.includes(`${attempt.view}|${attempt.state}` as typeof exactAxeStateKeys[number])
      || canonicalJson(attempt.viewport) !== canonicalJson(expected.viewport)) {
      throw new Error(`Gate rejected attempt identity mismatch: ${attempt.view}|${attempt.state}`);
    }
    const key = `${attempt.view}|${attempt.state}`;
    if (keys.has(key)) throw new Error(`Gate scan-attempt sidecar has a second collision for ${key}`);
    keys.add(key);
    stateKeyIndexes.push(exactAxeStateKeys.indexOf(key as typeof exactAxeStateKeys[number]));
    for (const [label, fence] of [["before", attempt.beforeFence], ["after", attempt.afterFence]] as const) {
      const { canonicalSha256: fenceHash, ...fenceBody } = fence;
      const { canonicalSha256: generationHash, ...generationBody } = fence.generation;
      if (fenceHash !== sha256(`${canonicalJson(fenceBody)}\n`)
        || generationHash !== sha256(`${canonicalJson(generationBody)}\n`)) {
        throw new Error(`Gate rejected attempt ${key} ${label} fence self-hash mismatch`);
      }
      requireExactGateDocumentBoundary(fence.trace, fence.client, `Gate rejected attempt ${key} ${label} fence`);
      requireExactGateLedgerClosure(fence.trace, fence.client, fence.localReportingArtifacts);
    }
    if (attempt.beforeFence.generation.id + 1 !== attempt.afterFence.generation.id
      || attempt.afterFence.trace.nextGeneration !== attempt.beforeFence.trace.nextGeneration + 1
      || attempt.afterFence.trace.nextSequence !== attempt.beforeFence.trace.nextSequence + exactReadbackPaths.length
      || attempt.afterFence.client.nextGeneration !== attempt.beforeFence.client.nextGeneration + 1
      || attempt.afterFence.client.nextRequestId !== attempt.beforeFence.client.nextRequestId + exactReadbackPaths.length
      || canonicalJson(attempt.afterFence.trace.requests.slice(0, attempt.beforeFence.trace.requests.length)) !== canonicalJson(attempt.beforeFence.trace.requests)
      || canonicalJson(attempt.afterFence.trace.generations.slice(0, attempt.beforeFence.trace.generations.length)) !== canonicalJson(attempt.beforeFence.trace.generations)
      || canonicalJson(attempt.afterFence.trace.deliveries.slice(0, attempt.beforeFence.trace.deliveries.length)) !== canonicalJson(attempt.beforeFence.trace.deliveries)
      || canonicalJson(attempt.afterFence.trace.aborted) !== canonicalJson(attempt.beforeFence.trace.aborted)
      || canonicalJson(attempt.afterFence.client.records.slice(0, attempt.beforeFence.client.records.length)) !== canonicalJson(attempt.beforeFence.client.records)
      || canonicalJson(attempt.afterFence.client.generations.slice(0, attempt.beforeFence.client.generations.length)) !== canonicalJson(attempt.beforeFence.client.generations)
      || attempt.afterFence.client.documentStartRequestId !== attempt.beforeFence.client.documentStartRequestId
      || attempt.afterFence.client.documentStartGeneration !== attempt.beforeFence.client.documentStartGeneration
      || canonicalJson(attempt.afterFence.localReportingArtifacts) !== canonicalJson(attempt.beforeFence.localReportingArtifacts)
      || !exactGateCurrentSource(attempt.beforeFence.fingerprint.source)
      || canonicalJson(attempt.afterFence.fingerprint.source) !== canonicalJson(attempt.beforeFence.fingerprint.source)
      || canonicalJson(exactMutableFingerprintWithoutSource(attempt.afterFence.fingerprint)) !== canonicalJson(exactMutableFingerprintWithoutSource(attempt.beforeFence.fingerprint))) {
      throw new Error(`Gate rejected attempt is not one closed periodic-refresh collision: ${key}`);
    }
    for (const [requestIndex, before] of attempt.beforeFence.generation.requests.entries()) {
      const after = attempt.afterFence.generation.requests[requestIndex];
      if (!after || after.pathname !== before.pathname
        || after.request.sequence !== attempt.beforeFence.trace.nextSequence + requestIndex + 1
        || after.request.clientTestStateId !== before.request.clientTestStateId
        || after.client.testStateId !== before.client.testStateId
        || after.delivery.testStateId !== before.delivery.testStateId
        || after.delivery.byteCount !== before.delivery.byteCount
        || after.delivery.bodySha256 !== before.delivery.bodySha256) {
        throw new Error(`Gate rejected attempt changed endpoint/test-state/body identity: ${key}:${before.pathname}`);
      }
    }
    expectExactGateObserverTransition(attempt.observer, attempt.beforeFence.fingerprint.source, true);
    expectExactGateLiveNodeClosure(attempt.liveNodeBindings, true);
    expectExactGateAxeClosure(attempt.axe, attempt.adjudications);
    expectExactDecorativeBindings(attempt.decorativeBindings);
    const previous = rejectedAttempts[attemptIndex - 1];
    if (previous && (attempt.beforeFence.generation.id < previous.afterFence.generation.id
      || attempt.beforeFence.trace.nextSequence < previous.afterFence.trace.nextSequence)) {
      throw new Error(`Gate rejected-attempt generation chronology moved backward: ${key}`);
    }
  }
  if (stateKeyIndexes.some((value, index) => index > 0 && value <= stateKeyIndexes[index - 1]!)) {
    throw new Error("Gate rejected attempts are not one strict exactStateKeys subsequence");
  }
  const scansByKey = new Map(expected.scans.map((scan) => [`${scan.view}|${scan.state}`, scan]));
  if (scansByKey.size !== exactAxeStateKeys.length
    || canonicalJson(expected.scans.map(({ view, state }) => `${view}|${state}`)) !== canonicalJson(exactAxeStateKeys)) {
    throw new Error("Gate accepted scan inventory is not the exact ordered state set");
  }
  for (const stateKey of exactAxeStateKeys) {
    const scan = scansByKey.get(stateKey);
    if (!scan) throw new Error(`Gate accepted scan missing: ${stateKey}`);
    const preAxe = preAxeStartFenceCollisions.filter(({ view, state }) => `${view}|${state}` === stateKey);
    const rejected = rejectedAttempts.filter(({ view, state }) => `${view}|${state}` === stateKey);
    if (preAxe.length > 1 || preAxe.length === 1 && (scan.gateAttemptProof.attempt !== 1
      || canonicalJson(preAxe[0]!.afterFence) !== canonicalJson(scan.gateAttemptProof.beforeFence))) {
      throw new Error(`Gate pre-Axe collision/accepted-before binding mismatch: ${stateKey}`);
    }
    if ((rejected.length === 1) !== (scan.gateAttemptProof.attempt === 2)) {
      throw new Error(`Gate rejected-attempt/accepted-attempt iff mismatch: ${stateKey}`);
    }
    if (rejected.length === 1 && canonicalJson(rejected[0]!.afterFence) !== canonicalJson(scan.gateAttemptProof.beforeFence)) {
      throw new Error(`Gate rejected after-fence does not byte-bind retry before-fence: ${stateKey}`);
    }
    if (rejected.length === 0 && scan.gateAttemptProof.attempt !== 1) {
      throw new Error(`Gate attempt-2 scan lacks its rejected sidecar record: ${stateKey}`);
    }
  }
  expectExactGateOrderedFenceHistory(expected.scans, rejectedAttempts, preAxeStartFenceCollisions);
  exactKeys(value.summary, ["executedRejectedAttempts", "periodicRefreshCollisions", "preAxeStartFenceCollisions", "rejectedAttempts", "secondCollisions", "statesRetried"], "Gate scan-attempt summary");
  const expectedSummary = {
    rejectedAttempts: rejectedAttempts.length,
    executedRejectedAttempts: rejectedAttempts.length,
    preAxeStartFenceCollisions: preAxeStartFenceCollisions.length,
    periodicRefreshCollisions: rejectedAttempts.length + preAxeStartFenceCollisions.length,
    statesRetried: keys.size,
    secondCollisions: 0 as const
  };
  if (canonicalJson(value.summary) !== canonicalJson(expectedSummary)) throw new Error("Gate scan-attempt summary mismatch");
}

type PublicBrowserArtifactFinding = "absolute-local-path" | "credential" | "secret" | "affirmative-private-or-authority-claim";

function publicBrowserArtifactFindingClasses(serialized: string): PublicBrowserArtifactFinding[] {
  const patterns: Array<[RegExp, PublicBrowserArtifactFinding]> = [
    [exactLocalPathPattern, "absolute-local-path"],
    [exactCredentialPattern, "credential"],
    [exactSecretAssignmentPattern, "secret"],
    [exactAffirmativePrivateClaimPattern, "affirmative-private-or-authority-claim"]
  ];
  return patterns.filter(([pattern]) => pattern.test(serialized)).map(([, finding]) => finding);
}

