function expectPublicBrowserArtifactSerialization(serialized: string, label: string) {
  const findings = publicBrowserArtifactFindingClasses(serialized);
  expect(findings, `${label} contains a prohibited private/credential/secret/local-path value`).toEqual([]);
}

function writeExactGateScanAttemptSidecar(
  testInfo: TestInfo,
  viewport: { width: number; height: number },
  head: string,
  scans: AxeScanEvidence[],
  rejectedAttempts: ExactRejectedGateAttempt[],
  preAxeStartFenceCollisions: ExactPreAxeStartFenceCollision[]
): ExactGateScanAttemptSidecarBinding {
  const retriedStateKeys = new Set([
    ...rejectedAttempts.map(({ view, state }) => `${view}|${state}`),
    ...preAxeStartFenceCollisions.map(({ view, state }) => `${view}|${state}`)
  ]);
  const body: ExactGateScanAttemptSidecarBody = {
    schemaVersion: gateScanAttemptSidecarSchema,
    source: { repository: exactRepository, head },
    project: testInfo.project.name,
    viewport,
    exactStateKeys: exactAxeStateKeys,
    maxAttemptsPerState: 2,
    maxStartFenceCapturesPerAxeAttempt: 2,
    preAxeStartFenceCollisions,
    rejectedAttempts,
    summary: {
      rejectedAttempts: rejectedAttempts.length,
      executedRejectedAttempts: rejectedAttempts.length,
      preAxeStartFenceCollisions: preAxeStartFenceCollisions.length,
      periodicRefreshCollisions: rejectedAttempts.length + preAxeStartFenceCollisions.length,
      statesRetried: retriedStateKeys.size,
      secondCollisions: 0
    }
  };
  const sidecar: ExactGateScanAttemptSidecar = { ...body, canonicalSha256: sha256(`${canonicalJson(body)}\n`) };
  assertExactGateScanAttemptSidecar(sidecar, { head, project: testInfo.project.name, viewport, scans });
  if (existsSync(accessibilityEvidenceDirectory) && (!lstatSync(accessibilityEvidenceDirectory).isDirectory()
    || lstatSync(accessibilityEvidenceDirectory).isSymbolicLink())) throw new Error("Accessibility evidence path is not a safe directory");
  mkdirSync(accessibilityEvidenceDirectory, { recursive: true, mode: 0o755 });
  const filename = `${testInfo.project.name}.gate-scan-attempts.json`;
  const target = path.join(accessibilityEvidenceDirectory, filename);
  const serialized = `${JSON.stringify(canonicalValue(sidecar), null, 2)}\n`;
  expectPublicBrowserArtifactSerialization(serialized, "Gate scan-attempt sidecar");
  writeFileSync(target, serialized, { encoding: "utf8", flag: "wx", mode: 0o644 });
  const stat = lstatSync(target);
  if (!stat.isFile() || stat.isSymbolicLink() || stat.nlink !== 1 || (stat.mode & 0o777) !== 0o644
    || stat.size !== Buffer.byteLength(serialized, "utf8") || readFileSync(target, "utf8") !== serialized) {
    throw new Error("Gate scan-attempt sidecar file identity mismatch");
  }
  return {
    schemaVersion: gateScanAttemptSidecarSchema,
    filename,
    byteCount: stat.size,
    sha256: sha256(Buffer.from(serialized, "utf8")),
    canonicalSha256: sidecar.canonicalSha256,
    rejectedAttemptCount: sidecar.summary.rejectedAttempts,
    executedRejectedAttemptCount: sidecar.summary.executedRejectedAttempts,
    periodicRefreshCollisionCount: sidecar.summary.periodicRefreshCollisions,
    statesRetried: sidecar.summary.statesRetried
  };
}

async function collectSemanticEvidence(page: Page) {
  await activateView(page, "Tree");
  const treeMark = page.locator(".tree-mark");
  const treeMarkLeaf = page.locator(".tree-mark-leaf");
  const sourceReadback = page.locator(".source-readback");
  const treeMap = page.locator(".tree-map");
  const treeEvidence = {
    treeMark: { role: await treeMark.getAttribute("role"), ariaLabel: await treeMark.getAttribute("aria-label"), leafAriaHidden: await treeMarkLeaf.getAttribute("aria-hidden") },
    sourceReadback: { role: await sourceReadback.getAttribute("role"), ariaLabel: await sourceReadback.getAttribute("aria-label") },
    treeMap: { role: await treeMap.getAttribute("role"), ariaLabel: await treeMap.getAttribute("aria-label") }
  };
  await activateView(page, "Action Center");
  const decisionButtons = page.locator(".decision-buttons");
  const evidence = {
    ...treeEvidence,
    decisionButtons: { role: await decisionButtons.getAttribute("role"), ariaLabel: await decisionButtons.getAttribute("aria-label") }
  };
  expect(evidence).toEqual({
    treeMark: { role: null, ariaLabel: null, leafAriaHidden: "true" },
    sourceReadback: { role: "group", ariaLabel: "Source readback" },
    treeMap: { role: "group", ariaLabel: "Clover Tree program graph" },
    decisionButtons: { role: "group", ariaLabel: "Synthetic owner decision" }
  });
  return evidence;
}

async function writeAccessibilityEvidence(
  page: Page,
  testInfo: TestInfo,
  viewport: { width: number; height: number },
  scans: AxeScanEvidence[],
  semantic: Awaited<ReturnType<typeof collectSemanticEvidence>>,
  keyboard: Record<string, unknown>,
  overflow: unknown[]
) {
  const stateKeys = scans.map(({ view, state }) => `${view}|${state}`);
  expect(stateKeys).toEqual([...exactAxeStateKeys]);
  const adjudications = scans.flatMap(({ view, state, adjudications: entries }) => entries.map((entry) => ({ view, state, ...entry })));
  const unresolved = adjudications.filter(({ classification, passes }) => classification === "unresolved" || !passes);
  const classes = Object.fromEntries(
    [...new Set(adjudications.map(({ classification }) => classification))].sort().map((classification) => [classification, adjudications.filter((entry) => entry.classification === classification).length])
  );
  const exemptions = adjudications.filter(({ exemption }) => exemption !== null).map(({ view, state, ruleId, target, html, messageKey, targetMatch, exemption }) => ({ view, state, ruleId, target, html, messageKey, targetMatch, exemption }));
  const passedRatios = scans.flatMap((scan) => scan.passes.filter(({ id }) => id === "color-contrast").flatMap((rule) => rule.nodes.map((node) => {
    const check = [...node.any, ...node.all, ...node.none].find(({ id }) => id === "color-contrast");
    const data = check?.data && typeof check.data === "object" ? check.data as Record<string, unknown> : {};
    const ratio = typeof data.contrastRatio === "number" ? data.contrastRatio : Number.NaN;
    const threshold = typeof data.expectedContrastRatio === "string" ? Number.parseFloat(data.expectedContrastRatio) : Number.NaN;
    return {
      sourceBucket: "passes" as const,
      view: scan.view,
      state: scan.state,
      target: node.target,
      html: node.html,
      foreground: typeof data.fgColor === "string" ? data.fgColor : null,
      background: typeof data.bgColor === "string" ? data.bgColor : null,
      ratio,
      threshold,
      passes: Number.isFinite(ratio) && Number.isFinite(threshold) && ratio >= threshold
    };
  })));
  const adjudicatedRatios = adjudications.filter(({ classification }) => classification === "measured-contrast").map(({ view, state, ruleId, target, html, messageKey, foreground, background, ratio, threshold, passes }) => ({ sourceBucket: "incomplete-adjudication" as const, view, state, ruleId, target, html, messageKey, foreground, background, ratio, threshold, passes }));
  const ratios = [...passedRatios, ...adjudicatedRatios];
  const meaningfulRatios = ratios.map(({ ratio }) => ratio).filter((ratio): ratio is number => typeof ratio === "number");
  expect(meaningfulRatios.length).toBe(ratios.length);
  expect(meaningfulRatios.length).toBeGreaterThan(0);
  expect(meaningfulRatios.every((ratio) => Number.isFinite(ratio) && ratio >= MIN_MEANINGFUL_CONTRAST_RATIO)).toBe(true);
  const minimumMeaningfulContrastRatio = meaningfulRatios.reduce((minimum, ratio) => Math.min(minimum, ratio), Number.POSITIVE_INFINITY);
  const runtime = [...(runtimeFindings.get(page) ?? [])];
  const renderedText = await page.locator("body").innerText();
  const privacyPatterns = [
    { id: "absolute-local-path", pattern: exactLocalPathPattern },
    { id: "credential", pattern: exactCredentialPattern },
    { id: "secret", pattern: exactSecretAssignmentPattern },
    { id: "affirmative-private-or-authority-claim", pattern: exactAffirmativePrivateClaimPattern }
  ];
  const privacyFindings = privacyPatterns.filter(({ pattern }) => pattern.test(renderedText)).map(({ id }) => id);
  expect(runtime).toEqual([]);
  expect(privacyFindings).toEqual([]);
  expect(unresolved).toEqual([]);
  expect(new Set(scans.map(({ axeVersion }) => axeVersion))).toEqual(new Set(["4.13.0"]));

  const head = sourceHead();
  const rejectedAttempts = gateRejectedAttempts.get(page);
  if (!rejectedAttempts) throw new Error("Exact Gate rejected-attempt ledger is unavailable at evidence write");
  const preAxeStartFenceCollisions = gatePreAxeStartFenceCollisions.get(page);
  if (!preAxeStartFenceCollisions) throw new Error("Exact Gate pre-Axe start-fence collision ledger is unavailable at evidence write");
  const priorClosure = buildGate04PriorClosure(scans, testInfo.project.name);
  const scanAttemptClosure = writeExactGateScanAttemptSidecar(
    testInfo,
    viewport,
    head,
    scans,
    rejectedAttempts,
    preAxeStartFenceCollisions
  );
  const expectedScreenshots = testInfo.project.name === "desktop-chromium"
    ? ["clover-tree-command-center-desktop-today.png"]
    : ["clover-tree-command-center-mobile-today.png", "clover-tree-command-center-mobile-action-center.png", "clover-tree-command-center-mobile-launch-studio.png"];
  const body = {
    schemaVersion: accessibilityEvidenceSchema,
    source: { repository: "chrisdortch/first", head },
    project: testInfo.project.name,
    viewport,
    exactViews,
    expectedScanCount: expectedAxeScansPerViewport,
    actualScanCount: scans.length,
    exactStateKeys: exactAxeStateKeys,
    stateKeys,
    axeVersion: "4.13.0",
    scanAttemptClosure,
    scans,
    adjudications,
    adjudicationClasses: classes,
    ratios,
    meaningfulContrast: {
      minimumRequiredRatio: MIN_MEANINGFUL_CONTRAST_RATIO,
      measuredCount: meaningfulRatios.length,
      minimumObservedRatio: minimumMeaningfulContrastRatio
    },
    exemptions,
    priorClosure,
    semantic,
    keyboard,
    overflow,
    runtime: { consoleErrors: 0, pageErrors: 0, requestFailures: 0, http5xx: 0, findings: runtime },
    privacy: { publicSanitized: true, privateDataAccessed: false, findings: privacyFindings },
    expectedScreenshots,
    summary: {
      scans: scans.length,
      passes: bucketSummary(scans, "passes"),
      violations: bucketSummary(scans, "violations"),
      incomplete: bucketSummary(scans, "incomplete"),
      inapplicable: bucketSummary(scans, "inapplicable"),
      adjudications: adjudications.length,
      closedContrastRatios: ratios.length,
      minimumMeaningfulContrastRatio,
      exemptions: exemptions.length,
      failingContrast: ratios.filter(({ passes }) => !passes).length,
      unresolved: unresolved.length,
      accessibilityViolations: scans.flatMap(({ violations }) => violations).length,
      consequentialAuthorityGranted: false
    },
    unresolved
  };
  const canonicalSha256 = sha256(`${canonicalJson(body)}\n`);
  const evidence = { ...body, canonicalSha256 };
  if (existsSync(accessibilityEvidenceDirectory) && (!lstatSync(accessibilityEvidenceDirectory).isDirectory()
    || lstatSync(accessibilityEvidenceDirectory).isSymbolicLink())) throw new Error("Accessibility evidence path is not a safe directory");
  mkdirSync(accessibilityEvidenceDirectory, { recursive: true, mode: 0o755 });
  const evidenceDirectoryStat = lstatSync(accessibilityEvidenceDirectory);
  if (!evidenceDirectoryStat.isDirectory() || evidenceDirectoryStat.isSymbolicLink()
    || (evidenceDirectoryStat.mode & 0o777) !== 0o755) throw new Error("Accessibility evidence directory identity mismatch");
  const evidencePath = path.join(accessibilityEvidenceDirectory, `${testInfo.project.name}.json`);
  if (existsSync(evidencePath)) throw new Error(`Accessibility evidence target must be fresh: ${evidencePath}`);
  const serialized = `${JSON.stringify(canonicalValue(evidence), null, 2)}\n`;
  expectPublicBrowserArtifactSerialization(serialized, "Gate accessibility evidence");
  writeFileSync(evidencePath, serialized, { encoding: "utf8", flag: "wx", mode: 0o644 });
  const evidenceStat = lstatSync(evidencePath);
  if (!evidenceStat.isFile() || evidenceStat.isSymbolicLink() || evidenceStat.nlink !== 1
    || (evidenceStat.mode & 0o777) !== 0o644 || evidenceStat.size !== Buffer.byteLength(serialized, "utf8")
    || readFileSync(evidencePath, "utf8") !== serialized) throw new Error("Gate accessibility evidence file identity mismatch");
  const sidecarBytes = readFileSync(path.join(accessibilityEvidenceDirectory, scanAttemptClosure.filename));
  await testInfo.attach(`clover-tree-gate-scan-attempts-${testInfo.project.name}.json`, { body: sidecarBytes, contentType: "application/json" });
  await testInfo.attach(`clover-tree-accessibility-${testInfo.project.name}.json`, { body: Buffer.from(serialized), contentType: "application/json" });
  return { evidencePath, canonicalSha256 };
}

test.beforeAll(async () => {
  exactFixtureServer = createServer(async (request, response) => {
    response.on("error", () => undefined);
    const target = new URL(request.url ?? "/", upstreamBrowserOrigin);
    const pathname = request.method === "GET" && target.search === "" && target.hash === ""
      && exactReadbackPaths.includes(target.pathname as ExactReadbackPath)
      ? target.pathname as ExactReadbackPath
      : null;
    const entry = pathname === null ? null : exactFixtureHandlers.get(pathname) ?? null;
    if (pathname !== null && entry?.transport === "same-origin-http-fixture") {
      try {
        if (!exactFixtureTestState) throw new Error("exact fixture test state is unavailable");
        const requestIdentityHeader = request.headers["x-clover-exact-client-request-identity"];
        const applicationGenerationHeader = request.headers["x-clover-exact-client-application-generation"];
        const testStateHeader = request.headers["x-clover-exact-test-state"];
        if (typeof requestIdentityHeader !== "string" || !/^[1-9][0-9]*$/u.test(requestIdentityHeader)
          || typeof applicationGenerationHeader !== "string" || !/^[1-9][0-9]*$/u.test(applicationGenerationHeader)
          || typeof testStateHeader !== "string" || testStateHeader !== exactFixtureTestState.id) {
          throw new Error(`exact client correlation is unavailable for ${pathname}`);
        }
        const requestIdentity = Number(requestIdentityHeader);
        const applicationGeneration = Number(applicationGenerationHeader);
        if (!Number.isSafeInteger(requestIdentity) || requestIdentity <= 0
          || !Number.isSafeInteger(applicationGeneration) || applicationGeneration <= 0) {
          throw new Error(`exact client correlation is invalid for ${pathname}`);
        }
        const fixture = await entry.respond();
        if (fixture.delayMs > 0) await new Promise((resolve) => setTimeout(resolve, fixture.delayMs));
        const delivery: ExactFixtureDelivery = {
          id: ++nextExactFixtureDeliveryId,
          requestIdentity,
          applicationGeneration,
          pathname,
          method: "GET",
          url: `${expectedBrowserOrigin}${pathname}`,
          testStateId: exactFixtureTestState.id,
          status: fixture.status,
          byteCount: fixture.body.byteLength,
          bodySha256: createHash("sha256").update(fixture.body).digest("hex"),
          body: Buffer.from(fixture.body),
          finished: false,
          cancelled: false,
          error: null
        };
        exactFixtureDeliveries.push(delivery);
        response.once("finish", () => { delivery.finished = true; });
        response.once("close", () => {
          if (!delivery.finished) delivery.cancelled = true;
        });
        response.once("error", (error) => {
          delivery.error = error.message;
          exactFixtureServerFindings.push(`${pathname} response stream failed: ${error.message}`);
        });
        request.once("aborted", () => { delivery.cancelled = true; });
        response.writeHead(fixture.status, {
          "Content-Length": String(fixture.body.byteLength),
          "X-Clover-Exact-Fixture-Sha256": delivery.bodySha256,
          "X-Clover-Exact-Fixture-Delivery": String(delivery.id),
          "X-Clover-Exact-Test-State": exactFixtureTestState.id,
          "X-Clover-Exact-Request-Identity": String(delivery.requestIdentity),
          "X-Clover-Exact-Application-Generation": String(delivery.applicationGeneration),
          ...fixture.headers
        });
        response.end(fixture.body);
      } catch (error) {
        const message = error instanceof Error ? error.message : "exact-fixture-handler-failed";
        exactFixtureServerFindings.push(`${pathname} fixture handler failed: ${message}`);
        if (!response.headersSent) response.writeHead(500, { "Content-Length": "0" });
        response.end();
      }
      return;
    }
    if (pathname !== null) {
      exactFixtureServerFindings.push(`${pathname} reached the proxy without an exact fixture response`);
      response.writeHead(503, { "Content-Length": "0" });
      response.end();
      return;
    }
    const upstream = new URL(`${target.pathname}${target.search}`, upstreamBrowserOrigin);
    const upstreamRequest = httpRequest(upstream, {
      method: request.method,
      headers: { ...request.headers, host: upstream.host }
    }, (upstreamResponse) => {
      response.writeHead(upstreamResponse.statusCode ?? 502, upstreamResponse.headers);
      upstreamResponse.pipe(response);
    });
    upstreamRequest.on("error", (error) => {
      exactFixtureServerFindings.push(`Upstream proxy failed for ${target.pathname}: ${error.message}`);
      if (!response.headersSent) response.writeHead(502, { "Content-Length": "0" });
      response.end();
    });
    request.on("aborted", () => upstreamRequest.destroy());
    request.pipe(upstreamRequest);
  });
  await new Promise<void>((resolve, reject) => {
    exactFixtureServer!.once("error", reject);
    exactFixtureServer!.listen(0, "127.0.0.1", resolve);
  });
  const address = exactFixtureServer.address() as AddressInfo | null;
  if (!address) throw new Error("Exact fixture proxy did not bind");
  expectedBrowserOrigin = `http://127.0.0.1:${address.port}`;
});

test.afterAll(async () => {
  exactFixtureServer?.closeAllConnections();
  await new Promise<void>((resolve) => exactFixtureServer?.close(() => resolve()) ?? resolve());
  exactFixtureServer = null;
  expectedBrowserOrigin = upstreamBrowserOrigin;
  exactFixtureHandlers.clear();
});

test.beforeEach(async ({ page }, testInfo) => {
  if (testInfo.title === exactSourceEvidenceMatrixTestTitle) return;
  const runtimeErrors: string[] = [];
  runtimeFindings.set(page, runtimeErrors);
  const blockers: ExactLocalBlockingFindings = {
    consoleErrors: [],
    pageErrors: [],
    http4xxOr5xx: [],
    unexpectedRequestFailures: [],
    malformedTruncatedOrUndecodableBodies: [],
    timeouts: [],
    applicationOrServerCancellations: [],
    otherUnexplainedAborts: [],
    privacyFindings: [],
    credentialFindings: [],
    secretFindings: [],
    localPathFindings: []
  };
  localBlockingFindings.set(page, blockers);
  exactFixturePage = page;
  exactFixtureHandlers.clear();
  exactFixtureServerFindings.length = 0;
  exactFixtureDeliveries.length = 0;
  const relativeTestFile = path.relative(process.cwd(), testInfo.file).split(path.sep).join("/");
  if (relativeTestFile !== "test/tree-command-center.e2e.spec.ts") throw new Error(`Unexpected exact test file identity: ${relativeTestFile}`);
  const viewport = testInfo.project.name.startsWith("mobile")
    ? { width: 390, height: 844 }
    : { width: 1440, height: 1000 };
  await page.setViewportSize(viewport);
  expect(page.viewportSize()).toEqual(viewport);
  const testStateBody = {
    file: relativeTestFile as ExactTestState["file"],
    project: testInfo.project.name,
    title: testInfo.title,
    repeatEachIndex: testInfo.repeatEachIndex,
    retry: testInfo.retry,
    viewport
  };
  const exactTestState: ExactTestState = {
    id: sha256(`${canonicalJson(testStateBody)}\n`),
    ...testStateBody
  };
  exactFixtureTestState = exactTestState;
  localClosureStates.set(page, {
    eligible: exactLocalReceiptTestTitles.includes(testInfo.title as typeof exactLocalReceiptTestTitles[number]),
    closureCompleted: false,
    closureGeneration: null,
    expectedRequestObservedAt: null,
    expectedGithubObservedAt: null,
    reportingArtifactGeneration: null,
    reportingArtifactRequestObservedAt: null,
    reportingArtifactGithubObservedAt: null,
    testState: exactTestState,
    rawEvents: [],
    independentCompletionEvidence: [],
    adjudications: []
  });
  await installExactClientConsumptionObserver(page, exactTestState.id);
  const readbackTrace: ReadbackRequestTrace = {
    nextSequence: 0,
    nextGeneration: 0,
    requestOrder: new WeakMap(),
    requests: [],
    generations: [],
    aborted: []
  };
  readbackRequestTraces.set(page, readbackTrace);
  page.on("console", (message) => {
    if (message.type() !== "error") return;
    runtimeErrors.push(message.text());
    if (localClosureStates.get(page)?.eligible) blockers.consoleErrors.push(message.text());
  });
  page.on("pageerror", (error) => {
    runtimeErrors.push(error.message);
    if (localClosureStates.get(page)?.eligible) blockers.pageErrors.push(error.message);
  });
  page.on("request", (request) => {
    const requestTarget = new URL(request.url());
    if (localClosureStates.get(page)?.eligible && (requestTarget.protocol === "http:" || requestTarget.protocol === "https:")
      && requestTarget.origin !== expectedBrowserOrigin) {
      addUniqueFinding(blockers.unexpectedRequestFailures,
        `unreviewed-cross-origin-request:${request.method()}:${requestTarget.origin}${requestTarget.pathname}`);
    }
    const pathname = exactReadbackPathname(request.url(), request.method());
    if (pathname === null) return;
    const record = beginExactReadbackRequest(readbackTrace, pathname, "browser-network");
    const headers = request.headers();
    const clientRequestIdentity = Number(headers["x-clover-exact-client-request-identity"] ?? Number.NaN);
    const clientApplicationGeneration = Number(headers["x-clover-exact-client-application-generation"] ?? Number.NaN);
    const clientTestStateId = headers["x-clover-exact-test-state"] ?? null;
    if (!Number.isSafeInteger(clientRequestIdentity) || clientRequestIdentity !== record.sequence
      || !Number.isSafeInteger(clientApplicationGeneration) || clientApplicationGeneration !== record.generation
      || clientTestStateId !== exactTestState.id) {
      const finding = `Malformed exact client request correlation for ${pathname}:${record.sequence}`;
      runtimeErrors.push(finding);
      if (localClosureStates.get(page)?.eligible) blockers.unexpectedRequestFailures.push(finding);
    } else {
      record.clientRequestIdentity = clientRequestIdentity;
      record.clientApplicationGeneration = clientApplicationGeneration;
      record.clientTestStateId = clientTestStateId;
    }
    readbackTrace.requestOrder.set(request, record);
  });
  page.on("requestfinished", (request) => {
    const record = readbackTrace.requestOrder.get(request);
    if (record) {
      record.terminal = "finished";
      exactFixtureBodyWasDelivered(record);
    }
  });
  page.on("requestfailed", (request) => {
    const errorText = request.failure()?.errorText ?? "failed";
    const record = readbackTrace.requestOrder.get(request);
    const pathname = record?.pathname ?? exactReadbackPathname(request.url(), request.method());
    const finding = pathname === null
      ? `${request.method()} ${request.url()} ${errorText}`
      : `${request.method()} ${expectedBrowserOrigin}${pathname} ${errorText}`;
    if (record) {
      record.terminal = "failed";
      record.failure = errorText;
    }
    if (pathname !== null && errorText === "net::ERR_ABORTED" && record !== undefined) {
      readbackTrace.aborted.push({ sequence: record.sequence, generation: record.generation, pathname, finding, acknowledged: false, classification: null });
      if (localClosureStates.get(page)?.eligible && pathname !== "/api/provenance") {
        blockers.otherUnexplainedAborts.push(`${pathname}:${record.sequence}:${errorText}`);
      }
      return;
    }
    runtimeErrors.push(finding);
    if (localClosureStates.get(page)?.eligible) blockers.unexpectedRequestFailures.push(finding);
  });
  page.on("response", (response) => {
    const record = readbackTrace.requestOrder.get(response.request());
    if (record) {
      record.status = response.status();
      const headers = response.headers();
      const deliveryHeader = headers["x-clover-exact-fixture-delivery"] ?? null;
      const bodySha256 = headers["x-clover-exact-fixture-sha256"] ?? null;
      const requestIdentityHeader = headers["x-clover-exact-request-identity"] ?? null;
      const generationHeader = headers["x-clover-exact-application-generation"] ?? null;
      const testStateHeader = headers["x-clover-exact-test-state"] ?? null;
      if (deliveryHeader !== null || bodySha256 !== null) {
        const deliveryId = deliveryHeader === null ? Number.NaN : Number(deliveryHeader);
        const requestIdentity = requestIdentityHeader === null ? Number.NaN : Number(requestIdentityHeader);
        const applicationGeneration = generationHeader === null ? Number.NaN : Number(generationHeader);
        const testState = localClosureStates.get(page)?.testState ?? null;
        if (!Number.isSafeInteger(deliveryId) || deliveryId <= 0 || !/^[0-9a-f]{64}$/u.test(bodySha256 ?? "")
          || requestIdentity !== record.sequence || applicationGeneration !== record.generation
          || requestIdentity !== record.clientRequestIdentity || applicationGeneration !== record.clientApplicationGeneration
          || testStateHeader !== testState?.id || testStateHeader !== record.clientTestStateId) {
          runtimeErrors.push(`Malformed exact fixture delivery binding for ${record.pathname}`);
        } else {
          record.transport = "same-origin-http-fixture";
          record.fixtureBodyState = "pending";
          record.fixtureDeliveryId = deliveryId;
          record.fixtureBodySha256 = bodySha256;
        }
      }
    }
    if (record && localClosureStates.get(page)?.eligible && response.status() !== 200) {
      blockers.unexpectedRequestFailures.push(`${response.status()} ${record.pathname}:${record.sequence}`);
    }
    if (response.status() >= 400) {
      if (localClosureStates.get(page)?.eligible) {
        const target = new URL(response.url());
        addUniqueFinding(blockers.http4xxOr5xx,
          `${response.status()} ${response.request().method()} ${target.origin}${target.pathname}`);
      }
      if (response.status() >= 500) runtimeErrors.push(`${response.status()} ${response.request().method()} ${response.url()}`);
    }
  });
  await installLiveTruthRoutes(page, { attestationSourceCommit: "f".repeat(40) });
  await gotoExactApp(page);
  await expect(page.locator(".source-readback [role=status]")).toContainText("phase observed");
  await settleInitialExactReadback(page);
});

test.afterEach(async ({ page }, testInfo) => {
  if (testInfo.title === exactSourceEvidenceMatrixTestTitle) return;
  await page.waitForTimeout(25);
  const trace = traceFor(page);
  await expect.poll(() => trace.requests.filter(({ terminal }) => terminal === "pending").length, {
    timeout: 5_000,
    message: "Exact readback requests must reach a finished or failed terminal before teardown"
  }).toBe(0);
  const unterminated = trace.requests.filter(({ terminal }) => terminal === "pending");
  expect(unterminated).toEqual([]);
  await expect.poll(() => trace.requests.filter((request) => request.transport === "same-origin-http-fixture"
    && !exactFixtureBodyWasDelivered(request)).length, {
    timeout: 5_000,
    message: "Every browser-observed exact fixture response must bind to a completed same-origin HTTP delivery"
  }).toBe(0);
  const undeliveredFixtureBodies = trace.requests.filter((request) => request.transport === "same-origin-http-fixture"
    && !exactFixtureBodyWasDelivered(request));
  expect(undeliveredFixtureBodies).toEqual([]);
  const unboundAborts = trace.aborted.filter((aborted) => !aborted.acknowledged);
  expect(unboundAborts, unboundAborts.map(({ finding }) => finding).join("\n")).toEqual([]);
  const findings = runtimeFindings.get(page) ?? [];
  expect(findings, findings.join("\n")).toEqual([]);
  expect(exactFixtureServerFindings, exactFixtureServerFindings.join("\n")).toEqual([]);
  expect(exactFixtureDeliveries.filter(({ finished }) => !finished), "Every exact same-origin fixture body must finish at the HTTP boundary").toEqual([]);
  await writeLocalSourceClosureReceipt(page, testInfo);
  exactFixturePage = null;
  exactFixtureTestState = null;
});

