test("Launch Studio transcript digest is exact-input bound, race-safe, failure-closed and recoverable", async ({ page }) => {
  await page.addInitScript(() => {
    type Behavior = "hold" | "sync-throw" | "async-reject" | "malformed";
    type HeldDigest = { algorithm: AlgorithmIdentifier; data: BufferSource; receiver: SubtleCrypto; resolve: (value: ArrayBuffer) => void; reject: (error: Error) => void };
    const originalDigest = SubtleCrypto.prototype.digest;
    const behaviors = new Map<string, Behavior>();
    behaviors.set("", "hold");
    const held = new Map<string, HeldDigest>();
    const control = {
      arm(text: string, behavior: Behavior) { behaviors.set(text, behavior); },
      isHeld(text: string) { return held.has(text); },
      release(text: string, outcome: "success" | "reject" | "malformed") {
        const pending = held.get(text);
        if (!pending) throw new Error(`missing held transcript digest: ${text}`);
        held.delete(text);
        if (outcome === "reject") pending.reject(new Error("controlled transcript digest rejection"));
        else if (outcome === "malformed") pending.resolve(Uint8Array.from([0]).buffer);
        else void originalDigest.call(pending.receiver, pending.algorithm, pending.data).then(pending.resolve, pending.reject);
      }
    };
    Object.defineProperty(window, "__cloverTranscriptDigestControl", { configurable: true, value: control });
    Object.defineProperty(SubtleCrypto.prototype, "digest", {
      configurable: true,
      value: function digest(this: SubtleCrypto, algorithm: AlgorithmIdentifier, data: BufferSource) {
        const bytes = data instanceof ArrayBuffer ? new Uint8Array(data) : new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
        const text = new TextDecoder().decode(bytes);
        const behavior = behaviors.get(text);
        if (!behavior) return originalDigest.call(this, algorithm, data);
        behaviors.delete(text);
        if (behavior === "sync-throw") throw new Error("controlled synchronous transcript digest failure");
        if (behavior === "async-reject") return Promise.reject(new Error("controlled asynchronous transcript digest failure"));
        if (behavior === "malformed") return Promise.resolve(Uint8Array.from([0]).buffer);
        return new Promise<ArrayBuffer>((resolve, reject) => held.set(text, { algorithm, data, receiver: this, resolve, reject }));
      }
    });
  });
  const transcriptReloadMarker = captureExactReadbackMarker(page);
  await page.reload({ waitUntil: "networkidle" });
  await acknowledgeExactSupersededReadbackAborts(page, transcriptReloadMarker);
  await page.getByRole("button", { name: "Launch Studio session", exact: true }).click();
  const input = page.getByLabel("Reviewed instruction or transcript");
  await expect(page.locator("#transcript-integrity[aria-live=polite]")).toHaveCount(1);
  const bytes = page.locator(".transcript-meta .metric").filter({ hasText: "UTF-8 bytes" }).locator("code");
  const digest = page.locator(".transcript-meta .metric").filter({ hasText: "SHA-256" }).locator("code");
  await expect(bytes).toHaveText("0");
  await expect(digest).toHaveText("calculating");
  await expect(digest).toHaveAttribute("title", "calculating");
  await expect.poll(() => page.evaluate(() => (window as unknown as { __cloverTranscriptDigestControl: { isHeld(value: string): boolean } }).__cloverTranscriptDigestControl.isHeld(""))).toBe(true);
  await page.evaluate(() => (window as unknown as { __cloverTranscriptDigestControl: { release(value: string, outcome: "success"): void } }).__cloverTranscriptDigestControl.release("", "success"));
  await expect(digest).toHaveText("e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855");
  await expect(digest).toHaveAttribute("title", "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855");
  const initialDigest = await digest.innerText();

  const textA = "Transcript digest A is deliberately held.";
  const textB = "Transcript digest B supersedes A and is also held.";
  const textC = "Transcript digest C is the exact current reviewed value.";
  await page.evaluate((text) => (window as unknown as { __cloverTranscriptDigestControl: { arm(value: string, behavior: "hold"): void } }).__cloverTranscriptDigestControl.arm(text, "hold"), textA);
  await input.fill(textA);
  await expect(digest).toHaveText("calculating");
  await expect(digest).toHaveAttribute("title", "calculating");
  await expect(digest).not.toHaveText(initialDigest);
  await expect(bytes).toHaveText(String(new TextEncoder().encode(textA).byteLength));
  await expect.poll(() => page.evaluate((text) => (window as unknown as { __cloverTranscriptDigestControl: { isHeld(value: string): boolean } }).__cloverTranscriptDigestControl.isHeld(text), textA)).toBe(true);
  await page.evaluate((text) => (window as unknown as { __cloverTranscriptDigestControl: { arm(value: string, behavior: "hold"): void } }).__cloverTranscriptDigestControl.arm(text, "hold"), textB);
  await input.fill(textB);
  await expect(digest).toHaveText("calculating");
  await expect(digest).toHaveAttribute("title", "calculating");
  await expect(bytes).toHaveText(String(new TextEncoder().encode(textB).byteLength));
  await expect.poll(() => page.evaluate((text) => (window as unknown as { __cloverTranscriptDigestControl: { isHeld(value: string): boolean } }).__cloverTranscriptDigestControl.isHeld(text), textB)).toBe(true);
  await page.evaluate((text) => (window as unknown as { __cloverTranscriptDigestControl: { release(value: string, outcome: "success"): void } }).__cloverTranscriptDigestControl.release(text, "success"), textA);
  await page.waitForTimeout(10);
  await expect(digest).toHaveText("calculating");
  await expect(bytes).toHaveText(String(new TextEncoder().encode(textB).byteLength));
  const unicodeTextC = `${textC} é 🌳`;
  await input.fill(unicodeTextC);
  await expect(digest).toHaveText(createHash("sha256").update(unicodeTextC).digest("hex"));
  const digestC = await digest.innerText();
  await expect(digest).toHaveAttribute("title", digestC);
  await expect(bytes).toHaveText(String(new TextEncoder().encode(unicodeTextC).byteLength));
  await page.evaluate((text) => (window as unknown as { __cloverTranscriptDigestControl: { release(value: string, outcome: "success"): void } }).__cloverTranscriptDigestControl.release(text, "success"), textB);
  await page.waitForTimeout(10);
  await expect(digest).toHaveText(digestC);

  const rejectedOld = "Transcript digest D rejects only after a newer value succeeds.";
  const afterRejectedOld = "Transcript digest E remains current after obsolete rejection.";
  await page.evaluate((text) => (window as unknown as { __cloverTranscriptDigestControl: { arm(value: string, behavior: "hold"): void } }).__cloverTranscriptDigestControl.arm(text, "hold"), rejectedOld);
  await input.fill(rejectedOld);
  await expect.poll(() => page.evaluate((text) => (window as unknown as { __cloverTranscriptDigestControl: { isHeld(value: string): boolean } }).__cloverTranscriptDigestControl.isHeld(text), rejectedOld)).toBe(true);
  await input.fill(afterRejectedOld);
  const afterRejectedDigest = createHash("sha256").update(afterRejectedOld).digest("hex");
  await expect(digest).toHaveText(afterRejectedDigest);
  await page.evaluate((text) => (window as unknown as { __cloverTranscriptDigestControl: { release(value: string, outcome: "reject"): void } }).__cloverTranscriptDigestControl.release(text, "reject"), rejectedOld);
  await page.waitForTimeout(25);
  await expect(digest).toHaveText(afterRejectedDigest);

  for (const [failureText, behavior] of [
    ["Transcript digest synchronous failure.", "sync-throw"],
    ["Transcript digest asynchronous failure.", "async-reject"],
    ["Transcript digest malformed fulfillment.", "malformed"]
  ] as const) {
    await page.evaluate(({ text, behavior: mode }) => (window as unknown as { __cloverTranscriptDigestControl: { arm(value: string, behavior: typeof mode): void } }).__cloverTranscriptDigestControl.arm(text, mode), { text: failureText, behavior });
    await input.fill(failureText);
    await expect(digest).toHaveText("unavailable");
    await expect(digest).toHaveAttribute("title", "unavailable");
    await expect(bytes).toHaveText(String(new TextEncoder().encode(failureText).byteLength));
  }
  const recovered = "Transcript digest recovers for exact current text.";
  await input.fill(recovered);
  await expect(digest).toHaveText(createHash("sha256").update(recovered).digest("hex"));
  await expect(bytes).toHaveText(String(new TextEncoder().encode(recovered).byteLength));
  await expect(digest).toHaveAttribute("title", await digest.innerText());

  const pendingUnmount = "Transcript digest pending during unmount.";
  await page.evaluate((text) => (window as unknown as { __cloverTranscriptDigestControl: { arm(value: string, behavior: "hold"): void } }).__cloverTranscriptDigestControl.arm(text, "hold"), pendingUnmount);
  await input.fill(pendingUnmount);
  await expect.poll(() => page.evaluate((text) => (window as unknown as { __cloverTranscriptDigestControl: { isHeld(value: string): boolean } }).__cloverTranscriptDigestControl.isHeld(text), pendingUnmount)).toBe(true);
  await page.getByRole("button", { name: "Today", exact: true }).click();
  await page.evaluate((text) => (window as unknown as { __cloverTranscriptDigestControl: { release(value: string, outcome: "success"): void } }).__cloverTranscriptDigestControl.release(text, "success"), pendingUnmount);
  await page.waitForTimeout(25);
  await expect(page.getByRole("heading", { level: 1, name: "Today" })).toBeVisible();
  await page.getByRole("button", { name: "Launch Studio session", exact: true }).click();
  await expect(page.getByLabel("Reviewed instruction or transcript")).toHaveValue("");
  await expect(page.locator(".transcript-meta .metric").filter({ hasText: "UTF-8 bytes" }).locator("code")).toHaveText("0");
  await expect(page.locator(".transcript-meta .metric").filter({ hasText: "SHA-256" }).locator("code")).toHaveText("e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855");
});

