test("successor saves serialize double clicks and reject an in-flight stale text result without forking history", async ({ page }) => {
  await page.addInitScript(() => {
    const originalDigest = SubtleCrypto.prototype.digest;
    const control: { target: string | null; releaseHeldDigest: (() => void) | null; heldCount: number; arm(text: string): void; release(): void } = {
      target: null,
      releaseHeldDigest: null,
      heldCount: 0,
      arm(text) { this.target = text; },
      release() {
        const release = this.releaseHeldDigest;
        this.releaseHeldDigest = null;
        release?.();
      }
    };
    Object.defineProperty(window, "__cloverSaveDigestControl", { configurable: true, value: control });
    Object.defineProperty(SubtleCrypto.prototype, "digest", {
      configurable: true,
      value: function digest(this: SubtleCrypto, algorithm: AlgorithmIdentifier, data: BufferSource) {
        const bytes = data instanceof ArrayBuffer
          ? new Uint8Array(data)
          : new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
        const decoded = new TextDecoder().decode(bytes);
        if (control.target !== null && decoded === control.target) {
          control.target = null;
          control.heldCount += 1;
          return new Promise<ArrayBuffer>((resolve, reject) => {
            control.releaseHeldDigest = () => { void originalDigest.call(this, algorithm, data).then(resolve, reject); };
          });
        }
        return originalDigest.call(this, algorithm, data);
      }
    });
  });
  await resetLiveTruthRoutes(page);
  const reloadMarker = captureExactReadbackMarker(page);
  await page.reload({ waitUntil: "networkidle" });
  await acknowledgeExactSupersededReadbackAborts(page, reloadMarker);
  await page.getByRole("button", { name: "Action Center", exact: true }).click();
  const input = page.getByLabel("Exact editable text");
  const save = page.getByRole("button", { name: "Save immutable successor", exact: true });
  const approve = page.getByRole("button", { name: "Approve packet", exact: true });
  const decision = page.locator(".decision-state");
  await input.fill(exactSyntheticOwnerText);
  await expect(save).toBeEnabled();
  await expect(approve).toBeEnabled();
  await approve.click();
  await expect(decision).toContainText("Decision: approved.");
  await page.evaluate((text) => (window as unknown as { __cloverSaveDigestControl: { arm(value: string): void } }).__cloverSaveDigestControl.arm(text), exactSyntheticOwnerText);
  await save.evaluate((button) => { (button as HTMLButtonElement).click(); (button as HTMLButtonElement).click(); });
  await expect.poll(() => page.evaluate(() => (window as unknown as { __cloverSaveDigestControl: { heldCount: number } }).__cloverSaveDigestControl.heldCount)).toBe(1);
  await expect(page.getByRole("button", { name: "Saving exact successor…", exact: true })).toBeDisabled();
  await expect(decision).toContainText("Decision: pending.");
  for (const buttonName of ["Approve packet", "Amend", "Decline", "Not now"] as const) {
    await expect(page.getByRole("button", { name: buttonName, exact: true })).toBeDisabled();
  }
  await approve.evaluate((button) => {
    const forcedButton = button as HTMLButtonElement;
    forcedButton.disabled = false;
    forcedButton.click();
    forcedButton.disabled = true;
  });
  await expect(decision).toContainText("Decision: pending.");
  await page.evaluate(() => (window as unknown as { __cloverSaveDigestControl: { release(): void } }).__cloverSaveDigestControl.release());
  await expect(page.getByText("Revision 1", { exact: true })).toBeVisible();
  await expect(decision).toContainText("Decision: pending.");
  await expect(page.locator(".revision-list > li")).toHaveCount(1);
  await save.click();
  await expect(page.getByText("Successor rejected: exact text is unchanged from the latest saved revision.", { exact: true })).toBeVisible();
  await expect(page.locator(".revision-list > li")).toHaveCount(1);

  const capturedText = `${exactSyntheticOwnerText} Candidate successor.`;
  await input.fill(capturedText);
  await expect(save).toBeEnabled();
  await page.evaluate((text) => (window as unknown as { __cloverSaveDigestControl: { arm(value: string): void } }).__cloverSaveDigestControl.arm(text), capturedText);
  await save.click();
  await expect.poll(() => page.evaluate(() => (window as unknown as { __cloverSaveDigestControl: { heldCount: number } }).__cloverSaveDigestControl.heldCount)).toBe(2);
  await input.fill(`${capturedText} Changed while saving.`);
  await page.evaluate(() => (window as unknown as { __cloverSaveDigestControl: { release(): void } }).__cloverSaveDigestControl.release());
  await expect(page.getByText("Successor was not saved because the owner text changed during calculation.", { exact: true })).toBeVisible();
  await expect(page.locator(".revision-list > li")).toHaveCount(1);

  const cycledText = `${exactSyntheticOwnerText} Cycle away and back without inheriting an old binding.`;
  await input.fill(cycledText);
  await expect(save).toBeEnabled();
  await page.evaluate((text) => (window as unknown as { __cloverSaveDigestControl: { arm(value: string): void } }).__cloverSaveDigestControl.arm(text), cycledText);
  await save.click();
  await expect.poll(() => page.evaluate(() => (window as unknown as { __cloverSaveDigestControl: { heldCount: number } }).__cloverSaveDigestControl.heldCount)).toBe(3);
  await input.fill(`${cycledText} temporary drift`);
  await input.fill(cycledText);
  await page.evaluate(() => (window as unknown as { __cloverSaveDigestControl: { release(): void } }).__cloverSaveDigestControl.release());
  await expect(page.getByText("Successor was not saved because the owner text changed during calculation.", { exact: true })).toBeVisible();
  await expect(page.locator(".revision-list > li")).toHaveCount(1);
});

test("an obsolete digest cannot enable or replace a newer exactly bound owner approval", async ({ page }) => {
  await page.addInitScript(() => {
    const originalDigest = SubtleCrypto.prototype.digest;
    let releaseHeldDigest: (() => void) | null = null;
    let held = false;
    const control = {
      isHeld: () => held,
      release: () => {
        const release = releaseHeldDigest;
        releaseHeldDigest = null;
        release?.();
      }
    };
    Object.defineProperty(window, "__cloverDigestControl", { configurable: true, value: control });
    Object.defineProperty(SubtleCrypto.prototype, "digest", {
      configurable: true,
      value: function digest(this: SubtleCrypto, algorithm: AlgorithmIdentifier, data: BufferSource) {
        const bytes = data instanceof ArrayBuffer
          ? new Uint8Array(data)
          : new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
        if (!held && new TextDecoder().decode(bytes).includes("held-old-owner-text")) {
          held = true;
          return new Promise<ArrayBuffer>((resolve, reject) => {
            releaseHeldDigest = () => { void originalDigest.call(this, algorithm, data).then(resolve, reject); };
          });
        }
        return originalDigest.call(this, algorithm, data);
      }
    });
  });
  await page.reload({ waitUntil: "networkidle" });
  await page.getByRole("button", { name: "Action Center", exact: true }).click();
  const input = page.getByLabel("Exact editable text");
  const approve = page.getByRole("button", { name: "Approve packet", exact: true });
  const decision = page.locator(".decision-state");
  const digest = page.locator(".owner-input-card .metric").filter({ hasText: "SHA-256" }).locator("code");

  await input.fill(exactSyntheticOwnerText);
  await expect(approve).toBeEnabled();
  await approve.click();
  await input.fill("Create a new project held-old-owner-text for SongAndStage.");
  await expect.poll(() => page.evaluate(() => (window as unknown as { __cloverDigestControl: { isHeld(): boolean } }).__cloverDigestControl.isHeld())).toBe(true);
  await expect(approve).toBeDisabled();
  await expect(decision).toContainText("Decision: pending.");

  const newerText = "Create a new project for Personal Launch Pods while the obsolete digest is unresolved.";
  await input.fill(newerText);
  await expect(approve).toBeEnabled();
  await approve.click();
  const newerDigest = await digest.innerText();
  await expect(decision).toContainText("Decision: approved.");
  await page.evaluate(() => (window as unknown as { __cloverDigestControl: { release(): void } }).__cloverDigestControl.release());
  await page.waitForTimeout(50);
  await expect(input).toHaveValue(newerText);
  await expect(digest).toHaveText(newerDigest);
  await expect(decision).toContainText("Decision: approved.");
});

test("malformed owner, packet, binding and successor digests fail closed and recover", async ({ page }) => {
  await page.addInitScript(() => {
    const originalDigest = SubtleCrypto.prototype.digest;
    let mode: "owner" | "packet" | "binding" | "wrong-save" | null = null;
    let target = "";
    const control = {
      arm(nextMode: "owner" | "packet" | "binding" | "wrong-save", nextTarget = "") { mode = nextMode; target = nextTarget; }
    };
    Object.defineProperty(window, "__cloverMalformedOwnerDigestControl", { configurable: true, value: control });
    Object.defineProperty(SubtleCrypto.prototype, "digest", {
      configurable: true,
      value: function digest(this: SubtleCrypto, algorithm: AlgorithmIdentifier, data: BufferSource) {
        const bytes = data instanceof ArrayBuffer ? new Uint8Array(data) : new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
        const text = new TextDecoder().decode(bytes);
        const wrongSave = mode === "wrong-save" && text === target;
        const matches = mode === "owner" && text === target
          || mode === "packet" && text.includes('"packetId": "packet:cloverapps-project-delta"') && text.includes('"targetModelProduct": "CloverApps collaboration"')
          || mode === "binding" && text.includes('"schemaVersion":"clover-owner-packet-binding-v1"');
        if (matches || wrongSave) {
          mode = null;
          if (wrongSave) return Promise.resolve(new Uint8Array(32).buffer);
          return Promise.resolve(Uint8Array.from([0]).buffer);
        }
        return originalDigest.call(this, algorithm, data);
      }
    });
  });
  const reloadMarker = captureExactReadbackMarker(page);
  await page.reload({ waitUntil: "networkidle" });
  await page.waitForTimeout(25);
  await acknowledgeExactSupersededReadbackAborts(page, reloadMarker);
  await page.getByRole("button", { name: "Action Center", exact: true }).click();
  const input = page.getByLabel("Exact editable text");
  const digest = page.locator(".owner-input-card .metric").filter({ hasText: "SHA-256" }).locator("code");
  const approve = page.getByRole("button", { name: "Approve packet", exact: true });
  const save = page.getByRole("button", { name: "Save immutable successor", exact: true });
  const arm = (mode: "owner" | "packet" | "binding" | "wrong-save", target = "") => page.evaluate(({ mode: nextMode, target: nextTarget }) => {
    (window as unknown as { __cloverMalformedOwnerDigestControl: { arm(mode: typeof nextMode, target: string): void } }).__cloverMalformedOwnerDigestControl.arm(nextMode, nextTarget);
  }, { mode, target });

  const malformedOwner = "Create a new project whose owner digest is malformed.";
  await arm("owner", malformedOwner);
  await input.fill(malformedOwner);
  await expect(digest).toHaveText("unavailable");
  await expect(approve).toBeDisabled();
  await expect(save).toBeDisabled();

  await arm("packet");
  await input.fill("Collaborate on a synthetic project with a malformed packet digest.");
  await expect(digest).toHaveText("unavailable");
  await expect(approve).toBeDisabled();

  await arm("binding");
  await input.fill("Create a new project whose final packet binding digest is malformed.");
  await expect(digest).toHaveText("unavailable");
  await expect(approve).toBeDisabled();

  const recovered = "Create a new project after every malformed digest was rejected.";
  await input.fill(recovered);
  await expect(digest).toHaveText(/^[a-f0-9]{64}$/u);
  await expect(approve).toBeEnabled();
  await arm("owner", recovered);
  await save.click();
  await expect(page.getByText("Successor calculation failed closed; nothing was saved.", { exact: true })).toBeVisible();
  await expect(page.locator(".revision-list > li")).toHaveCount(0);
  await expect(approve).toBeEnabled();
  await arm("wrong-save", recovered);
  await save.click();
  await expect(page.getByText("Successor calculation failed closed; nothing was saved.", { exact: true })).toBeVisible();
  await expect(page.locator(".revision-list > li")).toHaveCount(0);
});

test("browser speech is serialized, immediately invalidates approval and fails closed with cleanup", async ({ page }) => {
  await page.addInitScript(() => {
    type MockRecognition = {
      continuous: boolean;
      interimResults: boolean;
      lang: string;
      onresult: ((event: { results: ArrayLike<{ 0: { transcript: string }; length: number }> }) => void) | null;
      onerror: (() => void) | null;
      onend: (() => void) | null;
      start(): void;
      stop(): void;
    };
    const control: { active: MockRecognition | null; starts: number; stops: number; failConstruction: boolean; failStart: boolean; result(text: string): void; end(): void; error(): void; failNextConstruction(): void; failNextStart(): void } = {
      active: null,
      starts: 0,
      stops: 0,
      failConstruction: false,
      failStart: false,
      result(text) {
        this.active?.onresult?.({ results: [{ 0: { transcript: text }, length: 1 }] });
      },
      end() {
        const active = this.active;
        active?.onend?.();
        if (this.active === active) this.active = null;
      },
      error() {
        const active = this.active;
        active?.onerror?.();
        if (this.active === active) this.active = null;
      },
      failNextConstruction() {
        this.failConstruction = true;
      },
      failNextStart() {
        this.failStart = true;
      }
    };
    class FakeSpeechRecognition implements MockRecognition {
      continuous = false;
      interimResults = false;
      lang = "";
      onresult: MockRecognition["onresult"] = null;
      onerror: MockRecognition["onerror"] = null;
      onend: MockRecognition["onend"] = null;
      constructor() {
        if (control.failConstruction) {
          control.failConstruction = false;
          throw new Error("synthetic speech constructor failure");
        }
      }
      start() {
        control.starts += 1;
        if (control.failStart) {
          control.failStart = false;
          throw new Error("synthetic speech start failure");
        }
        control.active = this;
      }
      stop() { control.stops += 1; if (control.active === this) control.active = null; }
    }
    Object.defineProperty(window, "__cloverSpeechControl", { configurable: true, value: control });
    Object.defineProperty(window, "SpeechRecognition", { configurable: true, value: FakeSpeechRecognition });
  });
  await page.reload({ waitUntil: "networkidle" });
  await page.getByRole("button", { name: "Action Center", exact: true }).click();
  const input = page.getByLabel("Exact editable text");
  const approve = page.getByRole("button", { name: "Approve packet", exact: true });
  const speech = page.getByRole("button", { name: "Use permissioned browser speech", exact: true });
  const decision = page.locator(".decision-state");

  await input.fill(exactSyntheticOwnerText);
  await expect(approve).toBeEnabled();
  await approve.click();
  await speech.click();
  await expect(speech).toBeDisabled();
  await page.evaluate(() => (window as unknown as { __cloverSpeechControl: { result(text: string): void; end(): void } }).__cloverSpeechControl.result("Personal Launch Pods"));
  await expect(decision).toContainText("Decision: pending.");
  await page.evaluate(() => (window as unknown as { __cloverSpeechControl: { end(): void } }).__cloverSpeechControl.end());
  await expect(input).toHaveValue(`${exactSyntheticOwnerText} Personal Launch Pods`);
  await expect(speech).toBeEnabled();
  await expect(approve).toBeEnabled();

  const speechTextAfterResult = await input.inputValue();
  await speech.click();
  await page.evaluate(() => (window as unknown as { __cloverSpeechControl: { end(): void } }).__cloverSpeechControl.end());
  await expect(page.getByText("Speech recognition ended with no recognized text. Raw audio retained: false.", { exact: true })).toBeVisible();
  await expect(input).toHaveValue(speechTextAfterResult);
  await expect(speech).toBeEnabled();

  await page.evaluate(() => (window as unknown as { __cloverSpeechControl: { failNextConstruction(): void } }).__cloverSpeechControl.failNextConstruction());
  await speech.click();
  await expect(page.getByText("Speech permission or recognition failed closed. No audio was retained.", { exact: true })).toBeVisible();
  await expect(speech).toBeEnabled();
  await expect.poll(() => page.evaluate(() => (window as unknown as { __cloverSpeechControl: { active: unknown } }).__cloverSpeechControl.active)).toBeNull();

  await approve.click();
  await speech.click();
  await page.evaluate(() => (window as unknown as { __cloverSpeechControl: { error(): void } }).__cloverSpeechControl.error());
  await expect(page.getByText("Speech permission or recognition failed closed. No audio was retained.", { exact: true })).toBeVisible();
  await expect(speech).toBeEnabled();
  await page.evaluate(() => (window as unknown as { __cloverSpeechControl: { failNextStart(): void } }).__cloverSpeechControl.failNextStart());
  await speech.click();
  await expect(page.getByText("Speech permission or recognition failed closed. No audio was retained.", { exact: true })).toBeVisible();
  await expect(speech).toBeEnabled();
  await speech.click();
  await page.getByRole("button", { name: "Today", exact: true }).click();
  await expect.poll(() => page.evaluate(() => (window as unknown as { __cloverSpeechControl: { starts: number; stops: number } }).__cloverSpeechControl)).toMatchObject({ starts: 5, stops: 3 });
});

